<script setup lang="ts">
import {ref,watch,computed,nextTick} from 'vue'
import {api,APIError,t,lang,type MenuItem} from '../api'
const props=defineProps<{organizationId:number}>()
const items=ref<MenuItem[]>([]),busy=ref(false),error=ref(''),notice=ref(''),saved=ref(''),expanded=ref<string[]>([]);let revision=0
const dirty=computed(()=>JSON.stringify(items.value)!==saved.value)
function toggle(key:string){expanded.value=expanded.value.includes(key)?expanded.value.filter(value=>value!==key):[...expanded.value,key]}
function revealInvalid(event:Event){const field=event.target as HTMLInputElement;const key=field.closest<HTMLElement>('[data-menu-key]')?.dataset.menuKey;if(key&&!expanded.value.includes(key)){event.preventDefault();expanded.value.push(key);nextTick(()=>{field.focus();field.reportValidity()})}}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof APIError&&Object.keys(e.fields).length?Object.values(e.fields).join(' '):(e as Error).message}finally{busy.value=false}}
watch(()=>props.organizationId,()=>{const id=props.organizationId,rev=++revision;items.value=[];saved.value='[]';expanded.value=[];run(async()=>{const loaded=await api<MenuItem[]>(`/admin/menu?organization_id=${id}`);if(rev===revision){items.value=loaded.map(item=>({...item,parent:item.parent||''}));saved.value=JSON.stringify(items.value)}})},{immediate:true})
const rows=computed(()=>{const result:{item:MenuItem;depth:number;path:string}[]=[];function walk(parent='',depth=0,prefix=''){if(depth>=3)return;items.value.filter(item=>(item.parent||'')===parent).forEach((item,index)=>{const path=prefix+(index+1);result.push({item,depth,path});walk(item.key,depth+1,path+'.')})}walk();return result})
function siblings(item:MenuItem){return items.value.filter(other=>(other.parent||'')===(item.parent||''))}
function move(item:MenuItem,step:number){const adjacent=siblings(item),target=adjacent[adjacent.indexOf(item)+step];if(!target)return;const from=items.value.indexOf(item),to=items.value.indexOf(target);[items.value[from],items.value[to]]=[items.value[to],items.value[from]];notice.value=''}
function canParent(item:MenuItem,parent:string){const map=new Map(items.value.map(other=>[other.key,other]));for(const other of items.value){let key=other.key,depth=0;const seen=new Set<string>();while(key){if(seen.has(key)||++depth>3)return false;seen.add(key);const node=map.get(key);if(!node)return false;key=key===item.key?parent:node.parent||''}}return true}
function addLink(){items.value.push({key:'link-'+crypto.randomUUID(),label:{kk:'Жаңа сілтеме',ru:'Новая ссылка'},visible:true,parent:'',url:''});expanded.value.push(items.value.at(-1)!.key);notice.value=''}
function addGroup(){items.value.push({key:'group-'+crypto.randomUUID(),label:{kk:'Жаңа бөлім',ru:'Новый раздел'},visible:true,group:true,parent:''});expanded.value.push(items.value.at(-1)!.key);notice.value=''}
function removeGroup(group:MenuItem){for(const item of items.value)if(item.parent===group.key)item.parent=group.parent||'';items.value=items.value.filter(item=>item.key!==group.key);notice.value=''}
async function save(){items.value=(await api<MenuItem[]>(`/admin/menu?organization_id=${props.organizationId}`,{method:'PUT',body:JSON.stringify(items.value)})).map(item=>({...item,parent:item.parent||''}));saved.value=JSON.stringify(items.value);notice.value=t('Мәзір сақталды','Меню сохранено')}
</script>
<template><section class="editor-card menu-editor"><div class="section-heading"><div><p class="eyebrow">{{t('САЙТ НАВИГАЦИЯСЫ','НАВИГАЦИЯ САЙТА')}}</p><h1>{{t('Мәзір құрылымы','Структура меню')}}</h1></div><div class="actions"><button type="button" :disabled="busy||!items.length||items.length>=50" @click="addLink">+ {{t('Сілтеме қосу','Добавить ссылку')}}</button><button type="button" :disabled="busy||!items.length||items.length>=50" @click="addGroup">+ {{t('Бөлім қосу','Добавить группу')}}</button></div></div><p class="quiet">{{t('Атауын, мекенжайын және бөлімін өзгерту үшін тармақты басыңыз. Көрсеткілер бөлім ішіндегі ретті өзгертеді.','Нажмите на пункт, чтобы изменить название, адрес и группу. Стрелки меняют порядок внутри группы.')}}</p><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><form @submit.prevent="run(save)" @invalid.capture="revealInvalid" @input="notice=''" @change="notice=''"><div v-for="row in rows" :key="row.item.key" class="menu-row nested-menu-row" :class="{'menu-folder-row':row.item.group}" :style="{'--menu-depth':row.depth}" :data-menu-key="row.item.key"><div class="menu-row-heading"><button type="button" class="menu-row-toggle" :aria-expanded="expanded.includes(row.item.key)" :aria-controls="'menu-fields-'+row.item.key" @click="toggle(row.item.key)"><span class="menu-index">{{row.path}}</span><span class="menu-row-title"><strong>{{row.item.label[lang]}}</strong><small>{{row.item.group?t('Бөлім','Группа'):(row.item.url||'/'+(row.item.key==='home'?'':row.item.key))}}</small></span><span class="menu-status" :class="{'is-hidden':!row.item.visible}">{{row.item.visible?t('Көрінеді','Виден'):t('Жасырын','Скрыт')}}</span><span class="menu-expand" aria-hidden="true">{{expanded.includes(row.item.key)?'−':'+'}}</span></button><div class="move-controls"><button type="button" :disabled="busy||siblings(row.item)[0]===row.item" :aria-label="t('Жоғары жылжыту: ','Переместить выше: ')+row.item.label[lang]" @click="move(row.item,-1)">↑</button><button type="button" :disabled="busy||siblings(row.item).at(-1)===row.item" :aria-label="t('Төмен жылжыту: ','Переместить ниже: ')+row.item.label[lang]" @click="move(row.item,1)">↓</button></div></div><div v-show="expanded.includes(row.item.key)" :id="'menu-fields-'+row.item.key" class="menu-row-body"><div class="menu-fields"><div class="menu-labels"><label>ҚАЗ<input v-model="row.item.label.kk" required :disabled="busy"></label><label>РУС<input v-model="row.item.label.ru" required :disabled="busy"></label></div><label v-if="!row.item.group">{{t('URL мекенжайы','URL-адрес')}}<input v-model="row.item.url" :placeholder="row.item.key.startsWith('link-')?'/news немесе https://example.kz':'/'+(row.item.key==='home'?'':row.item.key)" :required="row.item.key.startsWith('link-')" maxlength="2048" :disabled="busy"><small class="quiet">{{t('Сайт жолы / немесе толық https:// мекенжайы. Бос болса — стандартты бөлім.',row.item.key.startsWith('link-')?'Путь от / или полный адрес https://.':'Путь от / или полный адрес https://. Пустое поле — стандартный раздел.')}}</small></label><div class="menu-placement"><label>{{t('Ата-ана бөлімі','Родительская группа')}}<select v-model="row.item.parent" :disabled="busy||row.item.key==='home'" @change="notice='' "><option value="">{{t('Жоғарғы деңгей','Верхний уровень')}}</option><option v-for="group in items.filter(item=>item.group&&item.key!==row.item.key)" :key="group.key" :value="group.key" :disabled="!canParent(row.item,group.key)">{{group.label[lang]}}</option></select></label><small class="quiet">{{row.item.group?t('Бөлім · ашылмалы мәзір','Группа · раскрывающееся меню'):(row.item.url||(row.item.key.startsWith('link-')?'URL':'/'+(row.item.key==='home'?'':row.item.key)))}}</small></div></div><div class="menu-controls"><label class="check"><input type="checkbox" v-model="row.item.visible" :disabled="busy||row.item.key==='home'">{{t('Көрсету','Показывать')}}</label><button v-if="row.item.group||row.item.key.startsWith('link-')" type="button" class="quiet" :disabled="busy" @click="removeGroup(row.item)">{{row.item.group?t('Топты алып тастау','Убрать группу'):t('Сілтемені жою','Удалить ссылку')}}</button></div></div></div><p class="quiet">{{t('Жасырын бөлім ішіндегі пункттер де жасырын болады. Топты алып тастау беттерді жоймайды.','Скрытая группа скрывает вложенные пункты. При удалении группы её пункты переходят на уровень выше; страницы сохраняются.')}}</p><div class="menu-save-bar"><span role="status">{{dirty?t('Сақталмаған өзгерістер','Есть несохранённые изменения'):t('Барлық өзгерістер сақталды','Все изменения сохранены')}}</span><button class="primary-button" :disabled="busy||!items.length||!dirty">{{busy?t('Сақталуда…','Сохранение…'):t('Мәзірді сақтау','Сохранить меню')}}</button></div></form></section></template>
